export type ParsedOverdueQuoteDefaultInstruction<
  TProgram extends string = typeof SHORTWIN_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** Permissionless executor and reward recipient; funds a roll record if needed. */
    keeper: TAccountMetas[0];
    config: TAccountMetas[1];
    market: TAccountMetas[2];
    financeMarket: TAccountMetas[3];
    position: TAccountMetas[4];
    borrower: TAccountMetas[5];
    exposure: TAccountMetas[6];
    marketVault: TAccountMetas[7];
    shareEpochRec: TAccountMetas[8];
    systemProgram: TAccountMetas[9];
    eventAuthority: TAccountMetas[10];
    program: TAccountMetas[11];
  };
  data: OverdueQuoteDefaultInstructionData;
};

export function parseOverdueQuoteDefaultInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedOverdueQuoteDefaultInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 12) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 12,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      keeper: getNextAccount(),
      config: getNextAccount(),
      market: getNextAccount(),
      financeMarket: getNextAccount(),
      position: getNextAccount(),
      borrower: getNextAccount(),
      exposure: getNextAccount(),
      marketVault: getNextAccount(),
      shareEpochRec: getNextAccount(),
      systemProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getOverdueQuoteDefaultInstructionDataDecoder().decode(
      instruction.data,
    ),
  };
}
